/**
 * Shell argument sanitization for safe command construction
 *
 * Prevents shell injection by validating arguments before command execution.
 */

/**
 * Strict allowlist regex for safe shell arguments: alphanumeric, dots, slashes,
 * hyphens, underscores, tildes, equals, colons, at-signs.
 * Rejects anything containing shell metacharacters.
 */
const SAFE_ARG_RE = /^[a-zA-Z0-9._/~=:@-]+$/;

/**
 * Validate that a string is safe to interpolate into a shell command.
 * Returns the string unchanged if it matches the allowlist, otherwise throws.
 */
export function assertSafeShellArg(arg: string, label = 'argument'): string {
  if (!arg || !SAFE_ARG_RE.test(arg)) {
    throw new Error(`Unsafe shell ${label}: ${JSON.stringify(arg)}`);
  }
  return arg;
}

/**
 * Validate that a string is a simple command name (no path separators or spaces).
 * For use with `command -v` / `which` checks.
 */
export function assertSafeCommandName(cmd: string): string {
  if (!cmd || !/^[a-zA-Z0-9_-]+$/.test(cmd)) {
    throw new Error(`Unsafe command name: ${JSON.stringify(cmd)}`);
  }
  return cmd;
}

/**
 * Git arguments that can execute arbitrary commands even without a shell.
 * These are interpreted by git itself, not by the OS shell.
 * See: https://codeql.github.com/codeql-query-help/javascript/js-command-line-injection/
 */
const DANGEROUS_GIT_ARGS = [
  '--upload-pack',
  '--receive-pack',
  '--exec',
  '-c',  // git -c core.fsmonitor=<cmd> / core.sshCommand=<cmd>
];

/**
 * Validate that a git argument array does not contain options that could
 * execute arbitrary commands (e.g., --upload-pack=<cmd>).
 * Throws if a dangerous option is detected.
 *
 * Safe to call on the full args array passed to execFileSync('git', args).
 */
export function assertSafeGitArgs(args: readonly string[]): void {
  for (const arg of args) {
    const lower = arg.toLowerCase();
    for (const dangerous of DANGEROUS_GIT_ARGS) {
      if (lower === dangerous || lower.startsWith(`${dangerous}=`)) {
        throw new Error(`Blocked dangerous git argument: ${JSON.stringify(arg)}`);
      }
    }
  }
}

/**
 * Validate that a session ID is safe for use in file paths and shell contexts.
 * Allows: alphanumeric, dots, hyphens, underscores.
 * Rejects: path separators, shell metacharacters, spaces.
 * Returns sanitized string (unsafe chars replaced with '_'), never throws.
 */
export function sanitizeSessionId(sessionId: string): string {
  if (!sessionId) return '';
  return sessionId.replace(/[^a-zA-Z0-9._-]/g, '_');
}
